// Supports BOTH Vapi tool shapes:
// 1) Classic function tool: body.message.toolCalls[] -> respond { results: [{ toolCallId, result }] }
// 2) API Request tool: flat body with { tool, ...params } -> respond flat mock JSON
const body = $input.first().json.body || {};
const message = body.message || {};
const toolCalls = message.toolCalls || [];

// Mock payloads keyed by tool name
function mockFor(name, args) {
  switch (name) {
    case 'route_call':
      return {
        status: 'Transferring',
        sip_uri: 'sip:' + String((args && args.department) || 'sales').toLowerCase() + '@voice.apex.com',
        extension: 'x4081',
      };
    case 'check_job_openings':
      return {
        openings: [
          'Software Engineer - Austin',
          'HR Manager - Remote',
        ],
      };
    case 'check_invoice_status':
      return {
        status: 'Paid',
        amount: '$4500.00',
        due_date: '2026-07-20',
      };
    case 'capture_sales_lead':
      return {
        status: 'Lead Logged',
        deal_id: 'DEAL-8821',
      };
    case 'send_confirmation':
      return {
        status: 'sent',
        channel: 'email',
      };
    default:
      return { error: 'Unknown tool: ' + name };
  }
}

if (toolCalls.length > 0) {
  // Classic function tool shape
  const results = toolCalls.map((tc) => {
    const fn = (tc && tc.function) || {};
    let args = fn.arguments;
    if (typeof args === 'string') {
      try { args = JSON.parse(args); } catch (e) { args = {}; }
    }
    return {
      toolCallId: tc.id,
      result: JSON.stringify(mockFor(fn.name, args || {})),
    };
  });
  return [{ json: { results } }];
}

// API Request tool shape: the tool name comes from a static body field 'tool'
const toolName = body.tool || body.name || 'unknown';
return [{ json: mockFor(toolName, body) }];
